/**
 * The simple footer (model footer@1): the brand, one line about the site, the links as a list in a nav and the
 * copyright line. Axes: layout (row: the brand beside a row of links, grid: the brand beside the links in two or
 * three columns, centered: everything centred).
 */
import { type ReactNode } from "react";
import { Block, Box, Container, LinkPlain, List, ListItem, Stack, Text } from "../compose";
import { cn, urlOf } from "../utils";
import type { FooterLink } from "./footer-simple.types";

export type FooterSimpleProps = {
  id: string;
  brand: string;
  description?: string;
  links: FooterLink[];
  copyright: string;
  padding?: "compact" | "standard" | "spacious";
  layout?: "row" | "grid" | "centered";
  landmarkLabel?: string;
};

export function FooterSimple({
  id,
  brand,
  description = "",
  links,
  copyright,
  padding = "compact",
  layout = "row",
  landmarkLabel,
}: FooterSimpleProps) {
  const frame =
    (layout as string) === "centered" ? "flex flex-col items-center gap-8 text-center"
    : (layout as string) === "grid" ? "grid grid-cols-1 gap-8 md:grid-cols-2"
    : "flex flex-col gap-8 md:flex-row md:items-start md:justify-between";
  const linkRow =
    (layout as string) === "grid" ? "grid grid-cols-2 gap-4 sm:grid-cols-3"
    : (layout as string) === "centered" ? "flex flex-wrap justify-center gap-6"
    : "flex flex-wrap gap-6";
  const copyAlign = ((layout as string) === "centered") ? "center" : "start";
  const copyText = ((layout as string) === "centered") ? "text-center" : "text-start";
  return (
    <Block
      tag="footer"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-label={landmarkLabel}
      data-slot="footer-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Stack gap="8" align="stretch">
          <Box className={frame}>
            <Stack gap="2" align={copyAlign} className="max-w-sm">
              <Text size="lg" weight="bold" className={copyText}>
                {brand}
              </Text>
              {description ? (
                <Text size="sm" className={cn("text-muted-foreground", copyText)}>
                  {description}
                </Text>
              ) : null}
            </Stack>
            <Box>
              <List tag="ul" className={cn("m-0 w-full list-none p-0", linkRow)}>
                {(links ?? []).map((l) => (
                  <ListItem key={l.id} data-slot="footer-link">
                    <LinkPlain href={urlOf(l.href)} className="text-muted-foreground hover:text-foreground">
                      <Text size="sm">
                        {l.label}
                      </Text>
                    </LinkPlain>
                  </ListItem>
                ))}
              </List>
            </Box>
          </Box>
          <Text size="xs" className={cn("text-muted-foreground", copyText)}>
            {copyright}
          </Text>
        </Stack>
      </Container>
    </Block>
  );
}

